import{_ as s,a0 as p,w as m,s as u,ao as l,I as o,x as e,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！ | LCTT x X-CMD","titleTemplate":false,"description":"還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！ | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！ | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Using Wine to Play Games On Linux？ Here’s Why You Should Switch To Steam Right Now","title":"還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！","tag":"201311","desc":""},"relativePath":"201311/Using Wine to Play Games On Linux？ Here’s Why You Should Switch To Steam Right Now.md","filePath":"[post].md"}'),r={name:"201311/Using Wine to Play Games On Linux？ Here’s Why You Should Switch To Steam Right Now.md"};function d(x,t,S,w,L,h){const n=p("Link");return m(),u("div",null,[t[11]||(t[11]=l('<h1 id="還在使用wine在linux上玩遊戲-別傻了-用steam吧" tabindex="-1">還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！ <a class="header-anchor" href="#還在使用wine在linux上玩遊戲-別傻了-用steam吧" aria-label="Permalink to “還在使用Wine在Linux上玩遊戲？別傻了，用Steam吧！”">​</a></h1><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2012/12/steamforlinux.png" alt=""></p><p>在過去的幾個月中，Steam平台受到了眾人的關注。並不是因為它帶來的遊戲，而是由於它拓展支持了不同的操作系統。假如你還沒有聽説過，那麼我告訴你，官方宣佈Steam計劃支持Linux，而且還在持續改進他們的beta版Linux客户端。花不了多長時間，就可以讓Steam的Linux客户端平穩下來，所以現在需要做的事情就只是把遊戲移植到Linux上了。</p><p>現在這項非常重要的服務已經可以在我們可愛的企鵝上使用，這兒還有好多理由指出你為什麼應該至少考慮一下轉換到Linux平台。</p><p>###性能###</p><p>我將以這個明顯的優點作為開始 - 使用Steam玩遊戲時，性能表現會好很多。當然，同使用Wine玩遊戲相比，那就更加顯得更加快速咯，因為遊戲是原生運行的，無需兼容層。性能是玩遊戲時最重要的因素之一，所以人們怎麼可以錯過這麼一個顯著的優點呢。</p><p>另外，我還注意到使用Steam玩遊戲比在Windows上玩遊戲還更加快速？同樣的硬件同一款遊戲，在linux上的表現比Windows上的表現還好。這一點別説別人，連我自己都沒想到。</p><p>###兼容性###</p><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2013/01/switch_steam_wine.jpg" alt=""></p><p>無論何時你購買一個遊戲，你都無法保證你購買的遊戲可以在Wine上良好運行。雖然有一個Wine兼容性資料庫，上面列出了Wine兼容的應用和遊戲，但是這只是告訴你有哪些想購買但是有可能不兼容的應用或遊戲，從而節省你的金錢。然而，使用Steam，那些支持Linux的所有遊戲都可以保證兼容，不需要去詢問任何兼容性問題。</p><p>###Steam的優點###</p><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2013/01/switch_steam_window.jpg" alt=""></p><p>當然，轉到Steam平台你就可以獲得它所有的好處。這包括：偶爾的價格優惠（尤其是那些在售的遊戲），完全在線體驗，不再需要物理介質，遊戲和客户端更新時你可以保持同步更新等。</p><p>例如，若你在你的電腦上重裝了系統，你只需打開Steam，坐在一旁休息，它就可以自動下載並安裝所有你安裝過的遊戲。在Windows和Mac OS X上，人們非常喜歡Steam的這種運作方式，所以這是一個你購買遊戲的好去處。</p><p>###後排的朋友，讓我聽到你的聲音！###</p><p>最後，轉到Steam平台，你是在表明你的態度。若Steam對於Linux平台的努力無法引起你遊戲的興趣，那麼我會感到非常驚訝。作為社區的一份子，我們需要對那些我們喜歡的項目表示支持。轉到Steam平台，不僅可以讓Steam公司覺得對於在Linux平台上的冒險值得，而且也告訴了其它人Linux完全可以作為遊戲平台——只是由於歷史的緣故，人們只是沒有在這方面投入足夠的時間和經歷使其取得突破而已。</p><p>假如我們向人們展示使用Linux的人們也是喜歡玩遊戲的，而且通過支持Linux是可以獲得利潤的，那麼人們就可能更加樂意開發支持Linux的遊戲。另外，我們都希望有更多的Linux原生遊戲，難道不是嗎？</p><p>###結論###</p><p>若你玩的遊戲Linux還不支持，那麼我完全能夠理解你對轉到Steam平台的懷疑。然而，你應當給它些時間，定期檢查一下更新。最終會有一些你玩的遊戲，還有一些你挺喜歡的新遊戲會成為那些支持Linux並在其上運行良好的遊戲的一部分。</p><p>你對Steam公司在Linux上的努力有什麼想法？你會考慮轉到Steam平台嗎？請在評論裏留言，讓我們知道你的想法！</p>',20)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),i(n,{href:"http://www.makeuseof.com/tag/using-wine-to-play-games-on-linux-heres-why-you-should-switch-to-steam-right-now/"},{default:a(()=>[...t[0]||(t[0]=[e("http://www.makeuseof.com/tag/using-wine-to-play-games-on-linux-heres-why-you-should-switch-to-steam-right-now/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=e("譯者：",-1)),i(n,{href:"https://github.com/Linux-pdz"},{default:a(()=>[...t[2]||(t[2]=[e("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const f=s(r,[["render",d]]);export{_ as __pageData,f as default};
